import React, { useState, useEffect } from 'react';
import {
  CheckCircleIcon,
  ExclamationTriangleIcon,
  XCircleIcon,
  ClockIcon,
  ArrowPathIcon,
  InformationCircleIcon,
  DocumentDuplicateIcon,
  EyeIcon
} from '@heroicons/react/24/outline';
import api from '../services/api';
import { useNotification } from '../hooks/useNotification';
import { formatDistanceToNow } from 'date-fns/formatDistanceToNow';
import { es } from 'date-fns/locale/es';

const DNSStatusPanel = ({ domainId = null, showHeader = true, autoRefresh = false }) => {
  const [domains, setDomains] = useState([]);
  const [loading, setLoading] = useState(true);
  const [verifying, setVerifying] = useState({});
  const [expandedDomain, setExpandedDomain] = useState(null);
  const { showNotification } = useNotification();

  useEffect(() => {
    fetchDomains();

    // Auto-refresh cada 30 segundos si está habilitado
    let interval;
    if (autoRefresh) {
      interval = setInterval(fetchDomains, 30000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [domainId, autoRefresh]);

  const fetchDomains = async () => {
    try {
      setLoading(true);
      let url = '/api/dominios/';

      if (domainId) {
        url = `/api/dominios/${domainId}/`;
      }

      const response = await api.get(url);

      if (domainId) {
        setDomains([response.data]);
      } else {
        setDomains(response.data.results || response.data);
      }
    } catch (error) {
      console.error('Error fetching domains:', error);
      showNotification('Error al cargar los dominios', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyDNS = async (domain) => {
    setVerifying(prev => ({ ...prev, [domain.id]: true }));

    try {
      const response = await api.post(`/api/dns-verification/${domain.id}/verify/`);

      if (response.data.task_id) {
        showNotification('Verificación DNS iniciada', 'info');

        // Esperar un momento y luego actualizar el estado
        setTimeout(() => {
          checkVerificationStatus(domain.id, response.data.task_id);
        }, 3000);
      }
    } catch (error) {
      console.error('Error starting DNS verification:', error);
      showNotification('Error al iniciar la verificación DNS', 'error');
      setVerifying(prev => ({ ...prev, [domain.id]: false }));
    }
  };

  const checkVerificationStatus = async (domainId, taskId) => {
    try {
      const response = await api.get(`/api/dns-verification/${domainId}/status/`);

      if (response.data.status === 'completed') {
        // Actualizar la información del dominio
        await fetchDomains();
        setVerifying(prev => ({ ...prev, [domainId]: false }));

        const hasErrors = response.data.results?.some(result => !result.valid);
        if (hasErrors) {
          showNotification('Algunos registros DNS no se pudieron verificar', 'warning');
        } else {
          showNotification('Verificación DNS completada exitosamente', 'success');
        }
      } else if (response.data.status === 'failed') {
        setVerifying(prev => ({ ...prev, [domainId]: false }));
        showNotification('Error en la verificación DNS', 'error');
      } else {
        // Seguir verificando
        setTimeout(() => {
          checkVerificationStatus(domainId, taskId);
        }, 2000);
      }
    } catch (error) {
      console.error('Error checking verification status:', error);
      setVerifying(prev => ({ ...prev, [domainId]: false }));
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'valid':
        return <CheckCircleIcon className="h-5 w-5 text-green-500" />;
      case 'invalid':
        return <XCircleIcon className="h-5 w-5 text-red-500" />;
      case 'warning':
        return <ExclamationTriangleIcon className="h-5 w-5 text-yellow-500" />;
      case 'pending':
        return <ClockIcon className="h-5 w-5 text-gray-400" />;
      default:
        return <ClockIcon className="h-5 w-5 text-gray-400" />;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'valid':
        return 'bg-green-50 border-green-200';
      case 'invalid':
        return 'bg-red-50 border-red-200';
      case 'warning':
        return 'bg-yellow-50 border-yellow-200';
      case 'pending':
        return 'bg-gray-50 border-gray-200';
      default:
        return 'bg-gray-50 border-gray-200';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'valid':
        return 'Válido';
      case 'invalid':
        return 'Error';
      case 'warning':
        return 'Advertencia';
      case 'pending':
        return 'Pendiente';
      default:
        return 'No verificado';
    }
  };

  const getOverallStatus = (domain) => {
    if (!domain.dns_records || domain.dns_records.length === 0) {
      return 'pending';
    }

    const hasInvalid = domain.dns_records.some(record => record.validation_status === 'invalid');
    const hasWarning = domain.dns_records.some(record => record.validation_status === 'warning');
    const allValid = domain.dns_records.every(record => record.validation_status === 'valid');

    if (hasInvalid) return 'invalid';
    if (hasWarning) return 'warning';
    if (allValid) return 'valid';
    return 'pending';
  };

  const copyToClipboard = async (text, label) => {
    try {
      await navigator.clipboard.writeText(text);
      showNotification(`${label} copiado al portapapeles`, 'success');
    } catch (error) {
      console.error('Error copying to clipboard:', error);
      showNotification('Error al copiar al portapapeles', 'error');
    }
  };

  if (loading) {
    return (
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
        {showHeader && (
          <h3 className="text-lg font-medium text-gray-900 mb-4">Estado DNS</h3>
        )}
        <div className="animate-pulse space-y-4">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="flex items-center space-x-4">
              <div className="rounded-full bg-gray-200 h-10 w-10"></div>
              <div className="flex-1 space-y-2">
                <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                <div className="h-3 bg-gray-200 rounded w-1/2"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
      {showHeader && (
        <div className="px-6 py-4 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-medium text-gray-900">Estado DNS</h3>

            {!domainId && (
              <button
                onClick={fetchDomains}
                disabled={loading}
                className="inline-flex items-center text-sm text-primary-600 hover:text-primary-800"
              >
                <ArrowPathIcon className={`h-4 w-4 mr-1 ${loading ? 'animate-spin' : ''}`} />
                Actualizar
              </button>
            )}
          </div>
        </div>
      )}

      <div className="p-6">
        {domains.length === 0 ? (
          <div className="text-center py-8">
            <InformationCircleIcon className="mx-auto h-12 w-12 text-gray-400" />
            <h3 className="mt-2 text-sm font-medium text-gray-900">
              No hay dominios configurados
            </h3>
            <p className="mt-1 text-sm text-gray-500">
              Añade un dominio para comenzar a monitorear su estado DNS.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {domains.map((domain) => {
              const overallStatus = getOverallStatus(domain);
              const isExpanded = expandedDomain === domain.id;
              const isVerifyingDomain = verifying[domain.id];

              return (
                <div
                  key={domain.id}
                  className={`border rounded-lg transition-colors ${
                    getStatusColor(overallStatus)
                  }`}
                >
                  <div className="p-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-3">
                        <div className="flex-shrink-0">
                          {getStatusIcon(overallStatus)}
                        </div>

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center space-x-2 mb-1">
                            <h4 className="text-sm font-medium text-gray-900 truncate">
                              {domain.nombre}
                            </h4>

                            <span className={`
                              inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium
                              ${
                                overallStatus === 'valid'
                                  ? 'bg-green-100 text-green-800'
                                  : overallStatus === 'invalid'
                                  ? 'bg-red-100 text-red-800'
                                  : overallStatus === 'warning'
                                  ? 'bg-yellow-100 text-yellow-800'
                                  : 'bg-gray-100 text-gray-800'
                              }
                            `}>
                              {getStatusText(overallStatus)}
                            </span>
                          </div>

                          <div className="flex items-center text-xs text-gray-500 space-x-4">
                            {domain.ultima_verificacion_dns ? (
                              <span className="flex items-center">
                                <ClockIcon className="h-3 w-3 mr-1" />
                                Verificado {formatDistanceToNow(new Date(domain.ultima_verificacion_dns), {
                                  addSuffix: true,
                                  locale: es
                                })}
                              </span>
                            ) : (
                              <span>No verificado</span>
                            )}

                            {domain.dns_records && (
                              <span>
                                {domain.dns_records.length} registro{domain.dns_records.length !== 1 ? 's' : ''}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center space-x-2">
                        <button
                          onClick={() => handleVerifyDNS(domain)}
                          disabled={isVerifyingDomain}
                          className="inline-flex items-center px-3 py-1.5 border border-transparent text-xs font-medium rounded text-primary-700 bg-primary-100 hover:bg-primary-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                          {isVerifyingDomain ? (
                            <>
                              <div className="animate-spin -ml-1 mr-2 h-3 w-3 border-2 border-primary-600 border-t-transparent rounded-full" />
                              Verificando...
                            </>
                          ) : (
                            <>
                              <ArrowPathIcon className="h-3 w-3 mr-1" />
                              Verificar
                            </>
                          )}
                        </button>

                        <button
                          onClick={() => setExpandedDomain(isExpanded ? null : domain.id)}
                          className="inline-flex items-center px-3 py-1.5 border border-gray-300 text-xs font-medium rounded text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500"
                        >
                          <EyeIcon className="h-3 w-3 mr-1" />
                          {isExpanded ? 'Ocultar' : 'Detalles'}
                        </button>
                      </div>
                    </div>
                  </div>

                  {/* Detalles expandidos */}
                  {isExpanded && domain.dns_records && (
                    <div className="border-t border-gray-200 p-4 bg-white bg-opacity-50">
                      <h5 className="text-sm font-medium text-gray-900 mb-3">
                        Registros DNS
                      </h5>

                      <div className="space-y-3">
                        {domain.dns_records.map((record) => (
                          <div
                            key={record.id}
                            className={`border rounded-lg p-3 ${
                              getStatusColor(record.validation_status)
                            }`}
                          >
                            <div className="flex items-start justify-between">
                              <div className="flex items-start space-x-3 flex-1">
                                <div className="flex-shrink-0 mt-0.5">
                                  {getStatusIcon(record.validation_status)}
                                </div>

                                <div className="flex-1 min-w-0">
                                  <div className="flex items-center space-x-2 mb-1">
                                    <h6 className="text-sm font-medium text-gray-900">
                                      {record.tipo}
                                    </h6>

                                    <span className={`
                                      inline-flex items-center px-2 py-0.5 rounded text-xs font-medium
                                      ${
                                        record.validation_status === 'valid'
                                          ? 'bg-green-100 text-green-800'
                                          : record.validation_status === 'invalid'
                                          ? 'bg-red-100 text-red-800'
                                          : record.validation_status === 'warning'
                                          ? 'bg-yellow-100 text-yellow-800'
                                          : 'bg-gray-100 text-gray-800'
                                      }
                                    `}>
                                      {getStatusText(record.validation_status)}
                                    </span>
                                  </div>

                                  {record.nombre && (
                                    <div className="text-xs text-gray-600 mb-1">
                                      Nombre: {record.nombre}
                                    </div>
                                  )}

                                  {record.valor && (
                                    <div className="font-mono text-xs bg-white border border-gray-200 rounded p-2 break-all mb-2">
                                      {record.valor}
                                    </div>
                                  )}

                                  {record.ultima_comprobacion && (
                                    <div className="text-xs text-gray-500">
                                      Última comprobación: {formatDistanceToNow(new Date(record.ultima_comprobacion), {
                                        addSuffix: true,
                                        locale: es
                                      })}
                                    </div>
                                  )}

                                  {record.error_message && (
                                    <div className="text-xs text-red-600 mt-1">
                                      Error: {record.error_message}
                                    </div>
                                  )}
                                </div>
                              </div>

                              {record.valor && (
                                <button
                                  onClick={() => copyToClipboard(record.valor, `Registro ${record.tipo}`)}
                                  className="ml-3 text-gray-400 hover:text-gray-600"
                                  title="Copiar valor"
                                >
                                  <DocumentDuplicateIcon className="h-4 w-4" />
                                </button>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* Información adicional */}
        {domains.length > 0 && (
          <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex">
              <InformationCircleIcon className="h-5 w-5 text-blue-400 flex-shrink-0" />
              <div className="ml-3">
                <h4 className="text-sm font-medium text-blue-800">
                  Sobre la Verificación DNS
                </h4>
                <div className="mt-2 text-sm text-blue-700">
                  <ul className="list-disc list-inside space-y-1">
                    <li>La verificación DNS puede tardar unos minutos en completarse</li>
                    <li>Los cambios DNS pueden tardar hasta 24-48 horas en propagarse</li>
                    <li>Se recomienda verificar periódicamente el estado de los registros</li>
                    <li>Los registros inválidos pueden afectar la entrega de correo</li>
                  </ul>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DNSStatusPanel;
